children.text:
/* Chargers */
#csd-nav .nav-list > li > a[href*="chargers-and-dispensing-gear"] ~ .csd-dropdown .csd-mega-inner {
    padding: 0 !important; margin-left: 0 !important;
}
/* Smokeware */
#csd-nav .nav-list > li > a[href*="smokeware-accessories"] ~ .csd-dropdown .csd-mega-inner {
    padding: 0 !important; margin-left: 0 !important;
}
/* Detox */
#csd-nav .nav-list > li > a[href*="detox-supplements-and-health"] ~ .csd-dropdown .csd-mega-inner {
    padding: 0 !important; margin-left: 0 !important;
}
#csd-nav .nav-list > li:nth-child(6) .csd-mega-inner { padding-left: 0 !important; }

.csd-brand-header { border-bottom: none !important; position: relative; padding-bottom: 10px; }
.csd-brand-header::after { content: ""; position: absolute; left: 0; bottom: 0; width: 100%; height: 1px; background-color: #215f93; }

ul.csd-cat-list { padding: 0px; }

/* ===================================
   RESET & VARS
=================================== */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --nav-bg:      #215f93;
  --nav-hover:   #1a4f7a;
  --drop-bg:     rgba(255,255,255,0.98);
  --accent:      #215f93;
  --text-nav:    #ffffff;
  --text-drop:   #1a1a1a;
  --hover-bg:    rgba(33,95,147,0.08);
  --hover-text:  #215f93;
  --img-bg:      #eef4fb;
  --border-col:  rgba(33,95,147,0.15);
  --promo-bg:    #f0f6fc;
  --shadow:      0 16px 48px rgba(0,0,0,0.18);
  --nav-max:     1500px;
  --promo-w:     200px;
  --mob-panel-w: 320px;
  --mob-bg:      #1a3d5c;
  --mob-header-h:52px;
}

/* ===================================
   DESKTOP NAV
=================================== */
#csd-nav {
  background: var(--nav-bg);
  border-bottom: 3px solid rgba(255,255,255,0.18);
  position: sticky;
  top: 0;
  z-index: 9000;
  width: 100%;
  padding: 0 !important;
}
#csd-nav .nav-container { position: relative; max-width: var(--nav-max); margin: 0 auto; }

.csd-sticky-fixed .csd-sticky-logo { display: flex !important; }

#csd-nav .nav-list { list-style: none; display: flex; align-items: stretch; flex-wrap: wrap; justify-content: center; transition: padding-left 0.3s ease; margin-bottom: 0 !important; }
.csd-sticky-fixed .nav-list { padding-left: 148px; }
#csd-nav .nav-list > li { position: static; }
#csd-nav .nav-list > li > a {
  display: flex; align-items: center; gap: 5px; padding: 16px 14px;
  color: var(--text-nav); text-decoration: none;
  font-family: 'Barlow', sans-serif; font-size: 12px; font-weight: 700;
  letter-spacing: .5px; text-transform: uppercase; white-space: nowrap;
  border-bottom: 3px solid transparent;
  transition: padding 0.3s ease, font-size 0.3s ease, background .15s;
}
.csd-sticky-fixed .nav-list > li > a { padding: 12px 10px; font-size: 10.5px; }
#csd-nav .nav-list > li > a:hover,
#csd-nav .nav-list > li.csd-open > a,
#csd-nav .nav-list > li > a.csd-active { background: var(--nav-hover); border-bottom-color: #fff; }
#csd-nav .csd-chevron { font-size: 8px; opacity: .75; display: inline-block; transition: transform .22s ease; }
#csd-nav .nav-list > li.csd-open .csd-chevron { transform: rotate(180deg); }

@keyframes csd-flash-rw {
  0%, 49%  { color: #ff0000; text-shadow: 0 0 8px rgba(255,0,0,0.5); }
  50%, 100%{ color: #ffffff; text-shadow: 0 0 8px rgba(255,255,255,0.5); }
}
.csd-flash-label { animation: csd-flash-rw 0.8s step-end infinite; font-weight: 900 !important; }

/* ── Dropdown base ── */
.csd-dropdown {
  display: flex;
  opacity: 0;
  pointer-events: none;
  transform: translateY(-6px);
  transition: opacity .2s ease, transform .2s ease;
  position: absolute;
  top: 100%;
  left: 0; right: 0;
  width: 100%;
  background: var(--drop-bg);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  border: 1.5px solid #215f93 !important;
  border-top: 3px solid var(--accent);
  box-shadow: var(--shadow);
  border-radius: 14px !important;
  overflow: hidden !important;
  z-index: 9100;
}

/* ✅ FIX #5: CRITICAL — Bridge gap between nav bar and dropdown so mouse can travel down without closing menu */
.csd-dropdown::before {
  content: "";
  position: absolute;
  top: -12px;       /* covers the gap above the dropdown */
  left: 0;
  right: 0;
  height: 12px;     /* matches the gap size */
  background: transparent;
  pointer-events: auto; /* catches mouse so menu stays open */
}

#csd-nav .nav-list > li.csd-open .csd-dropdown { opacity: 1; pointer-events: auto; transform: translateY(0); }

/* ── Inner grid ── */
.csd-mega-inner { display: grid; grid-template-columns: repeat(3, 1fr); flex: 1; padding: 20px 16px; gap: 0; min-width: 0; }
.csd-dropdown-sectioned .csd-mega-inner { grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); }
.csd-dropdown-sectioned.csd-two-sections .csd-mega-inner { grid-template-columns: 1fr 1fr; }

.csd-section-header { font-family: 'Barlow', sans-serif; font-size: 13px; font-weight: 800; letter-spacing: 2px; text-transform: uppercase; color: var(--accent); padding: 12px 0 8px 0; margin: 0 0 4px 0; border-bottom: 1.5px solid var(--accent); display: block; width: 100%; box-sizing: border-box; }

.csd-single-section-wrap { display: flex; flex-direction: column; flex: 1; min-width: 0; padding: 20px 16px; }
.csd-single-section-header { font-family: 'Barlow', sans-serif; font-size: 13px; font-weight: 800; letter-spacing: 2px; text-transform: uppercase; color: var(--accent); padding: 12px 16px 8px 16px; margin: 0 0 4px 0; display: block; width: 100%; box-sizing: border-box; }
.csd-single-section-header::after { content: ""; display: block; width: fit-content; min-width: 1200px; max-width: 260px; height: 1px; background: var(--accent); margin-top: 6px; }
.csd-single-section-wrap .csd-mega-inner { padding-top: 8px; }

.csd-mega-col { padding: 0 16px 12px 16px; border-right: 1px solid var(--border-col); min-width: 0; display: flex; flex-direction: column; }
.csd-mega-col:last-child { border-right: none; }
.csd-mega-col-split { flex: 1; }
.csd-split-inner { display: grid; grid-template-columns: 1fr 1fr; gap: 0; flex: 1; margin-top: 4px; }
.csd-split-subcol { padding-right: 4px; }
.csd-split-subcol:last-child { padding-right: 0; padding-left: 4px; }

.csd-cat-list { list-style: none; }
.csd-cat-list li { margin-bottom: 1px; }
.csd-cat-list li a { display: flex; align-items: center; gap: 10px; padding: 5px 8px; border-radius: 6px; color: var(--text-drop); text-decoration: none; font-family: 'Barlow', sans-serif; font-size: 14px; font-weight: 500; transition: background .12s, color .12s, padding-left .12s; white-space: nowrap; overflow: hidden; }
.csd-cat-list li a:hover { background: var(--hover-bg); color: var(--hover-text); font-weight: 600; padding-left: 12px; }
.csd-cat-list li a img { width: 55px; height: 55px; object-fit: contain; border-radius: 6px; background: var(--img-bg); padding: 3px; flex-shrink: 0; border: 1px solid rgba(33,95,147,0.1); }
.csd-split-subcol .csd-cat-list li a img { width: 55px; height: 55px; }
.csd-cat-list li a span { white-space: normal; line-height: 1.3; min-width: 0; }
.csd-cat-icon-ph { width: 30px; height: 30px; display: flex; align-items: center; justify-content: center; font-size: 14px; border-radius: 6px; background: #fff0f0; border: 1px solid rgba(200,0,0,0.18); flex-shrink: 0; }

/* ✅ FIX #4: Simple vertical list styles for Detox & N2O */
.csd-dropdown-simple {
  width: auto !important;
  min-width: 320px;
  max-width: 520px;
  right: auto !important; /* don't stretch full width */
}
.csd-simple-list-wrap {
  display: block;
  flex: 1;
  padding: 16px 20px;
  min-width: 220px;
}
.csd-simple-list-header {
  font-family: 'Barlow', sans-serif;
  font-size: 13px;
  font-weight: 800;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--accent);
  padding: 6px 0 8px 0;
  margin-bottom: 6px;
  border-bottom: 1.5px solid var(--accent);
  display: block;
}
.csd-simple-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 0;
}
.csd-simple-list li a {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 10px;
  border-radius: 6px;
  color: var(--text-drop);
  text-decoration: none;
  font-family: 'Barlow', sans-serif;
  font-size: 14px;
  font-weight: 500;
  transition: background .12s, color .12s, padding-left .12s;
  white-space: nowrap;
}
.csd-simple-list li a:hover {
  background: var(--hover-bg);
  color: var(--hover-text);
  font-weight: 600;
  padding-left: 14px;
}
.csd-simple-list li a img {
  width: 46px; height: 46px;
  object-fit: contain;
  border-radius: 6px;
  background: var(--img-bg);
  padding: 3px;
  flex-shrink: 0;
  border: 1px solid rgba(33,95,147,0.1);
}

/* ── Promo panel ── */
.csd-promo-panel { width: var(--promo-w); flex-shrink: 0; background: var(--promo-bg); border-left: 1px solid var(--border-col); display: flex; flex-direction: column; align-items: center; padding: 20px 14px; gap: 10px; text-align: center; overflow: hidden; }
.csd-promo-panel img { width: 100%; border-radius: 8px; object-fit: cover; border: 1px solid var(--border-col); }
.csd-promo-tag { font-size: 10px; letter-spacing: 2.5px; color: var(--accent); text-transform: uppercase; font-weight: 800; font-family: 'Barlow', sans-serif; }
.csd-promo-name { font-family: 'Bebas Neue', cursive; font-size: 21px; letter-spacing: 1px; line-height: 1.15; color: #1a1a1a; }
.csd-promo-btn { display: block; width: 100%; background: var(--accent); color: #fff; text-decoration: none; font-family: 'Barlow', sans-serif; font-size: 11px; font-weight: 800; letter-spacing: 1.5px; text-transform: uppercase; padding: 10px; border-radius: 5px; transition: background .18s, transform .1s; margin-top: auto; }
.csd-promo-btn:hover { background: #1a4f7a; transform: translateY(-1px); }

/* ── Brand grid ── */
.csd-brand-dropdown { flex-direction: column; padding: 18px 22px 14px; }
.csd-brand-header { font-family: 'Barlow', sans-serif; font-size: 15px; font-weight: 800; letter-spacing: 2px; text-transform: uppercase; color: var(--accent); padding-bottom: 12px; border-bottom: 1px solid var(--border-col); margin-bottom: 8px; padding: 20px 0px; }
.csd-brand-grid { display: grid; grid-template-columns: repeat(6, 1fr); gap: 10px; }
.csd-brand-card { display: flex; flex-direction: column; align-items: center; gap: 8px; padding: 12px 8px 10px; border-radius: 8px; text-decoration: none; border: 1px solid var(--border-col); background: #fff; transition: background .12s, border-color .12s, transform .13s, box-shadow .13s; text-align: center; min-height: 88px; justify-content: center; }
.csd-brand-card:hover { background: var(--hover-bg); border-color: var(--accent); transform: translateY(-2px); box-shadow: 0 4px 14px rgba(33,95,147,0.12); }
.csd-brand-logo { width: 100%; height: 120px; display: flex; align-items: center; justify-content: center; overflow: hidden; }
.csd-brand-logo img { max-width: 100%; max-height: 100%; width: auto; height: auto; object-fit: contain; }
.csd-brand-logo .csd-brand-initial { display: none; width: 44px; height: 44px; border-radius: 8px; background: var(--img-bg); border: 1px solid var(--border-col); align-items: center; justify-content: center; font-family: 'Barlow', sans-serif; font-size: 16px; font-weight: 800; color: var(--accent); text-transform: uppercase; }
.csd-brand-name { font-family: 'Barlow', sans-serif; font-size: 10.5px; font-weight: 700; color: var(--text-drop); letter-spacing: .3px; text-transform: uppercase; line-height: 1.25; word-break: break-word; max-width: 100%; }
.csd-brand-footer { margin-top: 12px; padding-top: 12px; border-top: 1px solid var(--border-col); text-align: center; }
.csd-brand-footer a { display: inline-flex; align-items: center; gap: 6px; background: var(--accent); color: #fff; text-decoration: none; font-family: 'Barlow', sans-serif; font-size: 11px; font-weight: 800; letter-spacing: 1.5px; text-transform: uppercase; padding: 9px 24px; border-radius: 5px; transition: background .18s; }
.csd-brand-footer a:hover { background: #1a4f7a; }

/* ===================================
   HAMBURGER
=================================== */
#csd-hamburger { display: none; background: none; border: none; cursor: pointer; padding: 12px 16px; -webkit-tap-highlight-color: transparent; user-select: none; align-items: center; justify-content: flex-end; background: var(--nav-bg); width: 100%; }
#csd-hamburger .csd-ham-icon { display: flex; flex-direction: column; justify-content: space-between; width: 24px; height: 18px; cursor: pointer; }
#csd-hamburger .csd-ham-icon span { display: block; width: 24px; height: 2px; background: #ffffff; border-radius: 0; transition: transform .25s ease, opacity .2s ease, width .2s ease; transform-origin: left center; }
#csd-hamburger[aria-expanded="true"] .csd-ham-icon span:nth-child(1) { transform: rotate(45deg) translate(1px,-1px); }
#csd-hamburger[aria-expanded="true"] .csd-ham-icon span:nth-child(2) { opacity: 0; width: 0; }
#csd-hamburger[aria-expanded="true"] .csd-ham-icon span:nth-child(3) { transform: rotate(-45deg) translate(1px,1px); }

/* ===================================
   MOBILE
=================================== */
@media (max-width: 767px) {
  #csd-hamburger { display: flex !important; justify-content: flex-start !important; padding: 10px 15px !important; background: transparent !important; }
  #csd-nav { background: var(--nav-bg); border-bottom: 3px solid rgba(255,255,255,0.18); padding: 0 !important; width: fit-content; }
}

@media (max-width: 767px) {
  #csd-nav .nav-list { display: none !important; }
  #csd-hamburger { display: flex !important; }
  #csd-mob-overlay { display: none; position: fixed; inset: 0; background: rgba(0,0,0,0.55); z-index: 10000; opacity: 0; transition: opacity .3s ease; }
  #csd-mob-overlay.csd-overlay-visible { display: block; opacity: 1; }
  #csd-mob-panel { position: fixed; top: 0; left: 0; width: var(--mob-panel-w); max-width: 88vw; height: 100vh; height: 100dvh; background: var(--mob-bg); z-index: 10001; transform: translateX(-100%); transition: transform .3s ease; display: flex; flex-direction: column; overflow: hidden; will-change: transform; }
  #csd-mob-panel.csd-panel-open { transform: translateX(0); }
  #csd-mob-header { display: flex; align-items: center; justify-content: space-between; height: var(--mob-header-h); min-height: var(--mob-header-h); padding: 0 16px; background: rgba(0,0,0,0.3); border-bottom: 1px solid rgba(255,255,255,0.12); flex-shrink: 0; }
  #csd-mob-back { display: flex; align-items: center; gap: 6px; color: rgba(255,255,255,0.85); font-family: 'Barlow', sans-serif; font-size: 12px; font-weight: 700; text-transform: uppercase; letter-spacing: .5px; cursor: pointer; -webkit-tap-highlight-color: transparent; min-width: 70px; visibility: hidden; pointer-events: none; transition: color .15s; }
  #csd-mob-back.visible { visibility: visible; pointer-events: auto; }
  #csd-mob-back::before { content: '←'; font-size: 16px; line-height: 1; }
  #csd-mob-back:active { color: #fff; }
  #csd-mob-title { font-family: 'Barlow', sans-serif; font-size: 13px; font-weight: 800; text-transform: uppercase; letter-spacing: 1px; color: #fff; text-align: center; flex: 1; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; padding: 0 8px; }
  #csd-mob-close { display: flex; align-items: center; justify-content: flex-end; width: 70px; color: rgba(255,255,255,0.7); font-size: 22px; cursor: pointer; -webkit-tap-highlight-color: transparent; line-height: 1; transition: color .15s; }
  #csd-mob-close:active { color: #fff; }
  #csd-mob-viewport { flex: 1; overflow: hidden; position: relative; }
  .csd-mob-screen { position: absolute; top: 0; left: 0; width: 100%; height: 100%; overflow-y: auto; -webkit-overflow-scrolling: touch; transition: transform .3s ease; will-change: transform; }
  #csd-mob-root { transform: translateX(0); }
  #csd-mob-root.slide-out { transform: translateX(-100%); }
  #csd-mob-sub { transform: translateX(100%); }
  #csd-mob-sub.slide-in { transform: translateX(0); }
  .csd-mob-row { display: flex; align-items: center; justify-content: space-between; padding: 0 16px; height: 52px; border-bottom: 1px solid rgba(255,255,255,0.08); cursor: pointer; -webkit-tap-highlight-color: transparent; text-decoration: none; transition: background .12s; }
  .csd-mob-row:active { background: rgba(255,255,255,0.07); }
  .csd-mob-row-label { font-family: 'Barlow', sans-serif; font-size: 13px; font-weight: 700; text-transform: uppercase; letter-spacing: .4px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; color: #ffffff !important; }
  .csd-mob-row-arrow { font-size: 16px; opacity: .6; flex-shrink: 0; margin-left: 8px; color: #ffffff !important; }
  .csd-mob-sub-section { padding: 10px 0 0; }
  .csd-mob-sub-label { padding: 8px 16px 6px; font-family: 'Barlow', sans-serif; font-size: 10px; font-weight: 900; letter-spacing: 2px; text-transform: uppercase; color: rgba(255,255,255,0.55) !important; }
  .csd-mob-section-group { border-top: 1px solid rgba(255,255,255,0.12); margin-top: 8px; padding-top: 4px; }
  .csd-mob-section-group:first-child { border-top: none; margin-top: 0; }
  .csd-mob-group-title { padding: 10px 16px 5px; font-family: 'Barlow', sans-serif; font-size: 10px; font-weight: 900; letter-spacing: 2px; text-transform: uppercase; color: #7ec8f5 !important; }
  .csd-mob-cat-item { display: flex; align-items: center; gap: 12px; padding: 0 16px; height: 52px; border-bottom: 1px solid rgba(255,255,255,0.07); text-decoration: none; color: #ffffff !important; font-family: 'Barlow', sans-serif; font-size: 13px; font-weight: 500; transition: background .1s, color .1s; -webkit-tap-highlight-color: transparent; }
  .csd-mob-cat-item:active { background: rgba(255,255,255,0.08); }
  .csd-mob-cat-item img { width: 34px; height: 34px; object-fit: contain; border-radius: 6px; background: rgba(255,255,255,0.1); padding: 3px; flex-shrink: 0; border: 1px solid rgba(255,255,255,0.12); }
  .csd-mob-cat-item .csd-mob-cat-icon-placeholder { width: 34px; height: 34px; border-radius: 6px; background: rgba(255,255,255,0.1); border: 1px solid rgba(255,255,255,0.12); flex-shrink: 0; display: flex; align-items: center; justify-content: center; font-size: 14px; }
  .csd-mob-cat-item span { white-space: normal; line-height: 1.3; color: #ffffff !important; }
  .csd-mob-brand-icon { width: 34px; height: 34px; border-radius: 6px; background: rgba(255,255,255,0.12); border: 1px solid rgba(255,255,255,0.15); flex-shrink: 0; display: flex; align-items: center; justify-content: center; overflow: hidden; }
  .csd-mob-brand-icon img { width: 30px; height: 30px; object-fit: contain; border-radius: 4px; background: transparent; border: none; padding: 0; }
  .csd-mob-brand-icon .csd-mob-brand-init { font-family: 'Barlow', sans-serif; font-size: 15px; font-weight: 800; color: #fff !important; text-transform: uppercase; }
  .csd-mob-promo { margin: 16px; background: rgba(255,255,255,0.08); border: 1px solid rgba(255,255,255,0.14); border-radius: 10px; padding: 16px; text-align: center; }
  .csd-mob-promo img { width: 80px; height: 80px; object-fit: contain; border-radius: 8px; margin-bottom: 10px; }
  .csd-mob-promo-name { font-family: 'Bebas Neue', cursive; font-size: 22px; letter-spacing: 1px; color: #ffffff !important; margin-bottom: 10px; line-height: 1.15; }
  .csd-mob-promo-btn { display: inline-block; background: var(--accent); color: #fff !important; text-decoration: none; font-family: 'Barlow', sans-serif; font-size: 11px; font-weight: 800; letter-spacing: 1.5px; text-transform: uppercase; padding: 10px 24px; border-radius: 6px; }
  .csd-mob-view-all { display: flex; align-items: center; justify-content: center; gap: 6px; margin: 12px 16px 20px; padding: 12px; background: var(--accent); border-radius: 7px; color: #fff !important; font-family: 'Barlow', sans-serif; font-size: 12px; font-weight: 800; letter-spacing: 1px; text-transform: uppercase; text-decoration: none; -webkit-tap-highlight-color: transparent; }
  #csd-mob-panel, #csd-mob-panel *, #csd-mob-panel a, #csd-mob-panel a:visited, #csd-mob-panel a:hover, #csd-mob-panel span, #csd-mob-panel div { color: #ffffff !important; }
  .csd-mob-flash { animation: csd-flash-rw 0.8s step-end infinite !important; font-weight: 900 !important; }
  body.csd-no-scroll { overflow: hidden !important; position: fixed; width: 100%; }
}

@media (min-width: 1025px) {
  #csd-hamburger   { display: none !important; }
  #csd-mob-overlay { display: none !important; }
  #csd-mob-panel   { display: none !important; }
  #csd-nav .nav-list { display: flex !important; }
}
@media (min-width: 768px) and (max-width: 1024px) {
  #csd-nav .nav-list { display: none !important; }
  #csd-hamburger { display: flex !important; }
  #csd-mob-panel, #csd-mob-overlay { display: block !important; }
}

