var ham      = document.getElementById('csd-hamburger');
var overlay  = document.getElementById('csd-mob-overlay');
var panel    = document.getElementById('csd-mob-panel');
var backBtn  = document.getElementById('csd-mob-back');
var titleEl  = document.getElementById('csd-mob-title');
var closeBtn = document.getElementById('csd-mob-close');
var rootScr  = document.getElementById('csd-mob-root');
var subScr   = document.getElementById('csd-mob-sub');
var isOpen   = false;
var inSub    = false;
var scrollPos= 0;

function openPanel() {
  scrollPos = window.pageYOffset;
  document.body.classList.add('csd-no-scroll');
  document.body.style.top = '-' + scrollPos + 'px';
  overlay.style.display = 'block';
  overlay.offsetHeight;
  overlay.classList.add('csd-overlay-visible');
  panel.classList.add('csd-panel-open');
  panel.setAttribute('aria-hidden', 'false');
  ham.setAttribute('aria-expanded', 'true');
  isOpen = true;
}
function closePanel() {
  panel.classList.remove('csd-panel-open');
  panel.setAttribute('aria-hidden', 'true');
  overlay.classList.remove('csd-overlay-visible');
  ham.setAttribute('aria-expanded', 'false');
  setTimeout(function() {
    overlay.style.display = 'none';
    document.body.classList.remove('csd-no-scroll');
    document.body.style.top = '';
    window.scrollTo(0, scrollPos);
  }, 310);
  if (inSub) resetToRoot();
  isOpen = false;
}
function openSub(key, label) {
  var d = CSD_MENU_DATA[key];
  if (!d) return;
  subScr.innerHTML = buildSubHTML(key, label, d);
  subScr.scrollTop = 0;
  rootScr.classList.add('slide-out');
  subScr.classList.add('slide-in');
  titleEl.textContent = label.toUpperCase();
  backBtn.classList.add('visible');
  inSub = true;
}
function resetToRoot() {
  rootScr.classList.remove('slide-out');
  subScr.classList.remove('slide-in');
  titleEl.textContent = 'MENU';
  backBtn.classList.remove('visible');
  inSub = false;
}
function esc(str) {
  var d = document.createElement('div');
  d.appendChild(document.createTextNode(String(str)));
  return d.innerHTML;
}

function buildSubHTML(key, label, d) {
  var html = '';
  if (d.type === 'brands') {
    html += '<div class="csd-mob-sub-section">';
    html += '<div class="csd-mob-sub-label">All Brands</div>';
    d.brands.forEach(function(b) {
      var init = b.name.charAt(0).toUpperCase();
      html += '<a class="csd-mob-cat-item" href="' + esc(b.href) + '">';
      html += '<div class="csd-mob-brand-icon">';
      if (b.logo) {
        html += '<img src="' + esc(b.logo) + '" alt="' + esc(b.name) + '"'
              + ' onerror="this.style.display=\'none\';this.parentNode.innerHTML=\'<span class=\\\'csd-mob-brand-init\\\'>' + init + '</span>\'">';
      } else {
        html += '<span class="csd-mob-brand-init">' + init + '</span>';
      }
      html += '</div>';
      html += '<span>' + esc(b.name) + '</span>';
      html += '</a>';
    });
    html += '</div>';
    html += '<a class="csd-mob-view-all" href="' + esc(d.all_href) + '">View All Brands →</a>';
    return html;
  }
  if (d.type === 'sections') {
    d.sections.forEach(function(section) {
      var title = section.title || '';
      var items = section.items || [];
      if (!items.length) return;
      html += '<div class="csd-mob-section-group">';
      if (title) html += '<div class="csd-mob-group-title">' + esc(title) + '</div>';
      items.forEach(function(item) {
        html += '<a class="csd-mob-cat-item" href="' + esc(item.href) + '">';
        if (item.img && item.img.trim()) {
          html += '<img src="' + esc(item.img.trim()) + '" alt="' + esc(item.label) + '" loading="lazy">';
        } else {
          html += '<div class="csd-mob-cat-icon-placeholder">🏷</div>';
        }
        html += '<span>' + esc(item.label) + '</span>';
        html += '</a>';
      });
      html += '</div>';
    });
    if (d.promo) {
      html += '<div class="csd-mob-promo">';
      html += '<img src="' + esc(d.promo.img) + '" alt="' + esc(d.promo.name) + '">';
      html += '<div class="csd-mob-promo-name">' + esc(d.promo.name) + '</div>';
      html += '<a class="csd-mob-promo-btn" href="' + esc(d.promo.href) + '">Shop Now →</a>';
      html += '</div>';
    }
  }
  return html;
}

/* Event bindings */
ham.addEventListener('click', function() { isOpen ? closePanel() : openPanel(); });
ham.addEventListener('keydown', function(e) { if (e.key==='Enter'||e.key===' ') { e.preventDefault(); ham.click(); } });
overlay.addEventListener('click', closePanel);
closeBtn.addEventListener('click', closePanel);
closeBtn.addEventListener('keydown', function(e) { if (e.key==='Enter'||e.key===' ') { e.preventDefault(); closePanel(); } });
backBtn.addEventListener('click', resetToRoot);
backBtn.addEventListener('keydown', function(e) { if (e.key==='Enter'||e.key===' ') { e.preventDefault(); resetToRoot(); } });

document.querySelectorAll('.csd-mob-trigger').forEach(function(el) {
  el.addEventListener('click', function() { openSub(el.getAttribute('data-key'), el.getAttribute('data-label')); });
  el.addEventListener('keydown', function(e) { if (e.key==='Enter'||e.key===' ') { e.preventDefault(); el.click(); } });
});

document.addEventListener('keydown', function(e) {
  if (e.key==='Escape') { if (inSub) resetToRoot(); else if (isOpen) closePanel(); }
});

/* ✅ FIX #5: Desktop hover — improved with delay buffer so gap doesn't close menu */
var desktopItems = document.querySelectorAll('#csd-nav .nav-list > li');
var closeTimers  = [];

desktopItems.forEach(function(li, idx) {
  var drop = li.querySelector('.csd-dropdown');
  var hoverCount = 0;
  closeTimers[idx] = null;

  function openDrop() {
    clearTimeout(closeTimers[idx]);
    desktopItems.forEach(function(el, i) { if (i !== idx) el.classList.remove('csd-open'); });
    li.classList.add('csd-open');
  }
  function scheduleClose() {
    clearTimeout(closeTimers[idx]);
    /* ✅ Increased delay from 100ms to 200ms — gives mouse time to cross gap */
    closeTimers[idx] = setTimeout(function() {
      if (hoverCount <= 0) li.classList.remove('csd-open');
    }, 200);
  }

  li.addEventListener('mouseenter', function() { hoverCount++; openDrop(); });
  li.addEventListener('mouseleave', function() { hoverCount = Math.max(0, hoverCount - 1); scheduleClose(); });

  if (drop) {
    drop.addEventListener('mouseenter', function() { hoverCount++; clearTimeout(closeTimers[idx]); li.classList.add('csd-open'); });
    drop.addEventListener('mouseleave', function() { hoverCount = Math.max(0, hoverCount - 1); scheduleClose(); });
  }
});

document.addEventListener('click', function(e) {
  if (!e.target.closest('#csd-nav')) {
    desktopItems.forEach(function(el) { el.classList.remove('csd-open'); });
  }
});

})();

