document.addEventListener('DOMContentLoaded', function() {
  const selector = '#wpforms-11156-field_26';
  const stopKeys = new Set(['ArrowUp','ArrowDown','PageUp','PageDown']);

  function disableKeyIncrement(input) {
    if (!input || input.__noKeyChange) return;
    input.__noKeyChange = true;

    input.addEventListener('keydown', function(e) {
      if (stopKeys.has(e.key)) e.preventDefault();
    });

    input.addEventListener('keyup', function(e) {
      if (stopKeys.has(e.key)) e.preventDefault();
    });

    // Remove number input arrows visually
    input.style.setProperty('-moz-appearance', 'textfield', 'important');
    input.style.setProperty('appearance', 'textfield', 'important');
  }

  // If field exists now, attach
  const field = document.querySelector(selector);
  if (field) disableKeyIncrement(field);

  // Watch for dynamically loaded form fields
  const observer = new MutationObserver(() => {
    const field = document.querySelector(selector);
    if (field) {
      disableKeyIncrement(field);
      observer.disconnect();
    }
  });
  observer.observe(document.documentElement, { childList: true, subtree: true });
});

