/* ── Fix ALL MetaSlider FlexSlider instances ── */
  .metaslider-flex .flex-viewport { overflow: hidden !important; }
  .metaslider-flex .slides {
    width: 100% !important;
    transform: none !important;
    transition: none !important;
    position: relative !important;
    display: block !important;
  }
  .metaslider-flex .slides li {
    position: absolute !important;
    top: 0 !important;
    left: 0 !important;
    width: 100% !important;
    float: none !important;
    margin: 0 !important;
    opacity: 0 !important;
    transition: opacity 0.6s ease-in-out !important;
    pointer-events: none !important;
    display: block !important;
  }
  .metaslider-flex .slides li.clone {
    display: none !important;
  }
  .metaslider-flex .slides li.ms-active-slide {
    opacity: 1 !important;
    position: relative !important;
    pointer-events: auto !important;
  }

  /* ── Arrow fix: always on top, always tappable ── */
  .metaslider-flex .flex-prev,
  .metaslider-flex .flex-next {
    position: absolute !important;
    z-index: 9999 !important;
    pointer-events: auto !important;
    cursor: pointer !important;
    /* Bigger tap target on mobile */
    min-width: 44px !important;
    min-height: 44px !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    -webkit-tap-highlight-color: transparent !important;
    touch-action: manipulation !important;
  }

  /* Hide all sliders until JS is ready — prevents flash on refresh */
  .metaslider-flex {
    visibility: hidden;
  }

(function(){
  function fixAllSliders(){
    var sliders = document.querySelectorAll('.metaslider-flex .flexslider');
    if(!sliders.length) return;

    sliders.forEach(function(sliderEl){
      if(sliderEl.dataset.msFixed === '1') return;
      sliderEl.dataset.msFixed = '1';

      var slides = Array.from(sliderEl.querySelectorAll('.slides li')).filter(function(li){
        return !li.classList.contains('clone') &&
               !li.classList.contains('flex-nav-prev') &&
               !li.classList.contains('flex-nav-next');
      });
      if(!slides.length) return;

      slides.forEach(function(li){
        li.classList.remove('flex-active-slide');
      });

      var current   = 0;
      var total     = slides.length;
      var autoTimer = null;
      var AUTO_MS   = 5000;
      var isAnimating = false; // prevent rapid double-tap

      function goTo(index){
        if(isAnimating) return;
        isAnimating = true;
        index = (index + total) % total;
        slides[current].classList.remove('ms-active-slide');
        current = index;
        slides[current].classList.add('ms-active-slide');
        // Unlock after transition completes
        setTimeout(function(){ isAnimating = false; }, 650);
      }

      function startAuto(){
        clearInterval(autoTimer);
        autoTimer = setInterval(function(){ goTo(current + 1); }, AUTO_MS);
      }

      slides[0].classList.add('ms-active-slide');

      // ── Arrow buttons — use pointerup to unify mouse + touch ──
      var prevBtn = sliderEl.querySelector('.flex-prev');
      var nextBtn = sliderEl.querySelector('.flex-next');

      function attachArrow(btn, direction){
        if(!btn) return;

        // Remove any existing FlexSlider listeners by cloning
        var fresh = btn.cloneNode(true);
        btn.parentNode.replaceChild(fresh, btn);

        var tapped = false; // prevent ghost click after touchend

        fresh.addEventListener('touchend', function(e){
          e.preventDefault(); // block the ghost mouse click
          e.stopPropagation();
          if(tapped) return;
          tapped = true;
          setTimeout(function(){ tapped = false; }, 400);
          clearInterval(autoTimer);
          goTo(current + direction);
          startAuto();
        }, {passive: false});

        fresh.addEventListener('click', function(e){
          e.preventDefault();
          e.stopPropagation();
          if(tapped) return; // already handled by touchend
          clearInterval(autoTimer);
          goTo(current + direction);
          startAuto();
        });

        // Return fresh node so callers can re-query if needed
        return fresh;
      }

      attachArrow(prevBtn, -1);
      attachArrow(nextBtn, +1);

      // ── Touch swipe on the slider body ──
      var touchStartX = 0;
      var touchStartY = 0;
      var swipeLocked = false;

      sliderEl.addEventListener('touchstart', function(e){
        touchStartX = e.changedTouches[0].screenX;
        touchStartY = e.changedTouches[0].screenY;
        swipeLocked = false;
      }, {passive: true});

      sliderEl.addEventListener('touchmove', function(e){
        // If scrolling vertically, lock out horizontal swipe
        if(!swipeLocked){
          var dx = Math.abs(e.changedTouches[0].screenX - touchStartX);
          var dy = Math.abs(e.changedTouches[0].screenY - touchStartY);
          if(dy > dx) swipeLocked = true;
        }
      }, {passive: true});

      sliderEl.addEventListener('touchend', function(e){
        if(swipeLocked) return;
        var delta = e.changedTouches[0].screenX - touchStartX;
        if(Math.abs(delta) > 50){
          clearInterval(autoTimer);
          goTo(delta < 0 ? current + 1 : current - 1);
          startAuto();
        }
      }, {passive: true});

      startAuto();
    });

    document.querySelectorAll('.metaslider-flex').forEach(function(el){
      el.style.visibility = 'visible';
    });
  }

  if(document.readyState === 'loading'){
    document.addEventListener('DOMContentLoaded', fixAllSliders);
  } else {
    fixAllSliders();
  }
  window.addEventListener('load', fixAllSliders);
})();

document.addEventListener("DOMContentLoaded", function () {

  const slider = document.querySelector('#metaslider-id-587731');
