(function(){
'use strict';

/* ── 0. REPLACE LOGO WITH VIDEO ── */
function injectLogoVideo(){
    var logoLink = document.querySelector(
        '.header-site-branding .header-logo-link, .header-logo .header-logo-link'
    );
    if(!logoLink) return;

    Array.prototype.forEach.call(logoLink.children, function(child){
        child.style.display = 'none';
    });

    var gif = document.createElement('img');
    gif.className = 'csd-logo-video-injected';
    gif.src = 'https://centralsmokedistro.com/wp-content/uploads/2026/04/download-1-1.gif';
	gif.alt = 'Central Smoke Distribution logo animation'; // Alt text
    gif.style.width  = '130px';
    gif.style.height = 'auto';
    gif.style.objectFit = 'contain';

    logoLink.appendChild(gif);
}

/* ── 0b. FIX ANY PARENT CONTAINER CONSTRAINING MASTHEAD WIDTH ── */
function fixHeaderWidth(){
    var masthead = document.querySelector('.masthead');
    if(!masthead) return;
    /* Walk up the DOM and remove max-width / overflow constraints
       on any wrapping container until we hit body */
    var el = masthead.parentElement;
    while(el && el !== document.body){
        var st = window.getComputedStyle(el);
        /* If a parent has a max-width or is a Bootstrap container, bust it open */
        if(
            st.maxWidth !== 'none' ||
            el.classList.contains('container') ||
            el.classList.contains('container-fluid') ||
            el.classList.contains('container-xl') ||
            el.classList.contains('container-lg')
        ){
            el.style.setProperty('max-width','100%','important');
            el.style.setProperty('width','100%','important');
            el.style.setProperty('padding-left','0','important');
            el.style.setProperty('padding-right','0','important');
        }
        el = el.parentElement;
    }
    /* Also force masthead itself */
    masthead.style.setProperty('width','100%','important');
    masthead.style.setProperty('max-width','100%','important');
    masthead.style.setProperty('left','0','important');
    masthead.style.setProperty('right','0','important');
    masthead.style.setProperty('box-sizing','border-box','important');
}

/* ── 1. GLOBAL STICKY BLUE NAV (SCROLL) ── */
function initStickyNav() {
    var blueNav = document.getElementById('csd-nav');
    if (!blueNav) blueNav = document.getElementById('lmm-custom-nav-wrapper');
    if (!blueNav) return;

    var placeholder = document.createElement('div');
    placeholder.className = 'csd-sticky-placeholder';
    placeholder.style.display = 'none';
    blueNav.parentNode.insertBefore(placeholder, blueNav);

    function checkSticky() {
        // If placeholder is not visible yet, measure against blueNav
        var target = (placeholder.style.display === 'none') ? blueNav : placeholder;
        var rect = target.getBoundingClientRect();

        if (rect.top <= 0) {
            if (!blueNav.classList.contains('csd-sticky-fixed')) {
                placeholder.style.height = blueNav.offsetHeight + 'px';
                placeholder.style.display = 'block';
                blueNav.classList.add('csd-sticky-fixed');
            }
        } else {
            if (blueNav.classList.contains('csd-sticky-fixed')) {
                placeholder.style.display = 'none';
                blueNav.classList.remove('csd-sticky-fixed');
            }
        }
    }

    window.addEventListener('scroll', checkSticky, {passive: true});
    window.addEventListener('resize', checkSticky, {passive: true});
}

/* ── 2. INJECT SCROLL SEARCH ICON ── */
function injectSearchIcon(){
    var icons = document.querySelector('.header-icons');
    if(!icons) return;
    var btn = document.createElement('div');
    btn.className = 'csd-hdr-search-btn header-icon';
    btn.title = 'Search'; btn.setAttribute('role','button');
    btn.innerHTML = '<svg viewBox="0 0 51.539 51.361" xmlns="http://www.w3.org/2000/svg"><path d="M51.539,49.356L37.247,35.065c3.273-3.74,5.272-8.623,5.272-13.983c0-11.742-9.518-21.26-21.26-21.26S0,9.339,0,21.082s9.518,21.26,21.26,21.26c5.361,0,10.244-1.999,13.983-5.272l14.292,14.292L51.539,49.356z M2.835,21.082c0-10.176,8.249-18.425,18.425-18.425s18.425,8.249,18.425,18.425S31.436,39.507,21.26,39.507S2.835,31.258,2.835,21.082z"/></svg>';
    icons.insertBefore(btn, icons.firstChild);
    btn.addEventListener('click', openOverlay);
}

/* ── 3. BUILD OVERLAY (clone of fibo) ── */
var overlay;

function buildOverlay(){
    /* Find the original FiboSearch widget */
    var origFibo = document.querySelector('.navbar-search .dgwt-wcas-search-wrapp')
                || document.querySelector('.dgwt-wcas-search-wrapp');

    overlay = document.createElement('div');
    overlay.className = 'pso-overlay';

    var box = document.createElement('div');
    box.className = 'pso-box';

    var holder = document.createElement('div');
    box.appendChild(holder);
    overlay.appendChild(box);
    /* ESC hint sits OUTSIDE the white box, on the dark backdrop */
    overlay.insertAdjacentHTML('beforeend','<div class="pso-hint">Press <strong>ESC</strong> to close</div>');
    document.body.appendChild(overlay);

    if(origFibo){
        /* Deep clone — preserves all markup including FiboSearch structure */
        var clone = origFibo.cloneNode(true);
        clone.style.cssText = '';
        clone.removeAttribute('style');
        holder.appendChild(clone);

        /*
         * Re-initialise FiboSearch on the clone.
         * We wait until the overlay is opened the first time so the
         * element is visible before jQuery tries to init AJAX.
         */
        overlay.addEventListener('pso:firstopen', function(){
            if(window.jQuery){
                var $clone = window.jQuery(clone);
                /* Trigger FiboSearch init events it listens for */
                $clone.find('.dgwt-wcas-search-input').trigger('focus');
            }
        }, {once: true});
    }

    overlay.addEventListener('click', function(e){
        if(e.target === overlay) closeOverlay();
    });
}

/* ── 4. OPEN / CLOSE ── */
var _firstOpen = true;
function openOverlay(){
    if(!overlay) return;
    if(_firstOpen){
        overlay.dispatchEvent(new Event('pso:firstopen'));
        _firstOpen = false;
    }
    overlay.classList.add('pso-open');
    document.body.style.overflow = 'hidden';
    setTimeout(function(){
        var inp = overlay.querySelector('.dgwt-wcas-search-input');
        if(inp){ inp.focus(); }

        /* Force scroll on suggestions-wrapp directly */
        function forceScroll(){
            var wrapp = overlay.querySelector('.dgwt-wcas-suggestions-wrapp');
            if(wrapp){
                wrapp.style.setProperty('overflow-y','scroll','important');
                wrapp.style.setProperty('overflow-x','hidden','important');
                wrapp.style.setProperty('max-height','350px','important');
                wrapp.style.setProperty('height','auto','important');
                wrapp.style.setProperty('display','block','important');
            }
            /* Inner list — let it grow naturally */
            var inner = overlay.querySelector('.dgwt-wcas-suggestions');
            if(inner){
                inner.style.setProperty('overflow','visible','important');
                inner.style.setProperty('max-height','none','important');
                inner.style.setProperty('height','auto','important');
            }
        }
        forceScroll();

        /* Also watch for suggestions appearing via MutationObserver */
        var target = overlay.querySelector('.dgwt-wcas-search-wrapp');
        if(target && window.MutationObserver){
            var obs = new MutationObserver(function(){ forceScroll(); });
            obs.observe(target, {childList:true, subtree:true});
        }
    }, 130);
}
function closeOverlay(){
    if(!overlay) return;
    overlay.classList.remove('pso-open');
    document.body.style.overflow = '';
    setTimeout(function(){
        var inp = overlay.querySelector('.dgwt-wcas-search-input');
        if(inp) inp.value = '';
    }, 380);
}
document.addEventListener('keydown', function(e){ if(e.key==='Escape') closeOverlay(); });

/* ── 5. BIND ORIGINAL HEADER SEARCH → opens overlay ── */
function bindHeaderSearch(){
    var wrap = document.querySelector('.navbar-search');
    if(wrap) wrap.addEventListener('click', function(e){
        e.preventDefault();
        openOverlay();
    });
}

/* ── INIT ── */
document.addEventListener('DOMContentLoaded', function(){
    injectLogoVideo();
    fixHeaderWidth();

    // Safety check: ensure blue nav is under the white masthead in DOM order
    var blueNavWrapper = document.getElementById('lmm-custom-nav-wrapper');
    var whiteMast = document.querySelector('.masthead');
    if (blueNavWrapper && whiteMast && whiteMast.parentElement) {
        // If blueNavWrapper is ABOVE the white masthead in the DOM, move it BELOW
        if (blueNavWrapper.compareDocumentPosition(whiteMast) & Node.DOCUMENT_POSITION_FOLLOWING) {
            whiteMast.parentElement.insertBefore(blueNavWrapper, whiteMast.nextSibling);
        }
    }

    initStickyNav();
    buildOverlay();
    injectSearchIcon();
    bindHeaderSearch();
    window.addEventListener('load', function(){
        fixHeaderWidth();
    });
});

})();

