jQuery(function($){

    /* =====================================
       NOTIFY ME BUTTON
       ===================================== */

    $(document).on('click','.notify-button',function(){

        var btn = $(this);

        if(btn.hasClass('loading')){
            return false;
        }

        btn.addClass('loading');
        btn.val('Opening...');

        setTimeout(function(){

            if(btn.val() === 'Opening...'){
                btn.val('Notify Me');
            }

            btn.removeClass('loading');

        },3000);

    });

    /* =====================================
       SUBSCRIBE BUTTON
       ===================================== */

    $(document).on('click','.cwgstock_button',function(){

        var btn = $(this);

        if(btn.hasClass('loading')){
            return false;
        }

        btn.addClass('loading');

        if(btn.is('input')){

            btn.data('old-text',btn.val());

            btn.val('Submitting...');

        }else{

            btn.data('old-text',btn.text());

            btn.text('Submitting...');

        }

        if(!$('.cwg-temp-message').length){

            $('.cwgstock_output').before(
                '<div class="cwg-temp-message">Please wait, processing your request...</div>'
            );

        }

        if(!btn.parent().find('.cwg-btn-spinner').length){

            btn.after('<span class="cwg-btn-spinner"></span>');

        }

    });

    /* =====================================
       AJAX COMPLETE
       ===================================== */

    $(document).ajaxComplete(function(){

        $('.cwg-temp-message').remove();

        $('.cwg-btn-spinner').remove();

        $('.cwgstock_button.loading').each(function(){

            var btn = $(this);

            btn.removeClass('loading');

            if(btn.is('input')){

                btn.val(
                    btn.data('old-text')
                    ? btn.data('old-text')
                    : 'Subscribe Now'
                );

            }else{

                btn.text(
                    btn.data('old-text')
                    ? btn.data('old-text')
                    : 'Subscribe Now'
                );

            }

        });

    });

    /* =====================================
       KEEP POPUP ABOVE HEADER
       ===================================== */

    function forcePopupTop(){

        $('.swal2-container').css({
            'z-index':'999999999'
        });

        $('.swal2-popup').css({
            'z-index':'999999999'
        });

    }

    setInterval(forcePopupTop,500);

});

