(function () {

        // --- Cookie helpers (run client-side so caching plugins can't break this) ---
        function getCookie(name) {
            const match = document.cookie.match(
                new RegExp('(^| )' + name + '=([^;]+)')
            );
            return match ? decodeURIComponent(match[2]) : null;
        }

        function setCookie(name, value, days) {
            const d = new Date();
            d.setTime(d.getTime() + days * 24 * 60 * 60 * 1000);
            const secure = location.protocol === 'https:' ? '; Secure' : '';
            document.cookie =
                name + '=' + encodeURIComponent(value) +
                '; expires=' + d.toUTCString() +
                '; path=/; SameSite=Lax' + secure;
        }

        // If already verified, never show the gate — exit immediately, no flash.
        if (getCookie('cs_age_verified') === 'true') {
            return;
        }

        document.addEventListener('DOMContentLoaded', function () {

            const popup   = document.getElementById('cs-age-gate');
            const stepAsk = document.getElementById('cs-step-ask');
            const stepDeny= document.getElementById('cs-step-deny');

            if (!popup) return;

            popup.classList.add('show');
            document.body.style.overflow = 'hidden';

            // Guard against caching/optimization plugins (WP Rocket "Delay JS",
            // LiteSpeed, etc.) that replay the visitor's triggering click after
            // the script finally loads — that replayed click can land on a
            // button the instant it appears. A real visitor physically cannot
            // click within this window, so we ignore clicks that happen too soon.
            const readyAt = Date.now() + 400;
            function isReplayedClick() {
                return Date.now() < readyAt;
            }

            document.getElementById('cs-btn-yes').addEventListener('click', function (e) {
                if (isReplayedClick()) { e.preventDefault(); e.stopPropagation(); return; }

                setCookie('cs_age_verified', 'true', 30); // remembered for 30 days

                popup.classList.remove('show');
                document.body.style.overflow = 'auto';

                setTimeout(function () {
                    popup.remove();
                }, 600);
            });

            document.getElementById('cs-btn-no').addEventListener('click', function (e) {
                if (isReplayedClick()) { e.preventDefault(); e.stopPropagation(); return; }
                stepAsk.style.opacity = '0';
                stepAsk.style.transform = 'translateX(-20px)';

                setTimeout(function () {
                    stepAsk.style.display = 'none';
                    stepDeny.style.display = 'block';

                    void stepDeny.offsetWidth;

                    stepDeny.style.opacity = '1';
                    stepDeny.style.transform = 'translateX(0)';
                }, 400);
            });

        });

    })();

