(function() {
  // Remove old styles
  document.querySelectorAll('#pw-toggle-fix-style').forEach(el => el.remove());

  // Add CSS
  const style = document.createElement('style');
  style.id = 'pw-toggle-fix-style';
  style.textContent = `
    .password-input {
      position: relative !important;
      width: 100% !important;
      display: inline-block !important;
      overflow: visible !important;
    }
    .password-input input[type="password"],
    .password-input input[type="text"] {
      width: 100% !important;
      box-sizing: border-box !important;
      padding-right: 44px !important;
      position: relative !important;
      z-index: 2 !important;
      transition: background-color 0.3s ease, border-color 0.3s ease;
    }
    /* Input highlight */
    .password-input input.highlighted {
      background-color: #e8f3ff !important;
      border-color: #0086ff !important;
    }

    .password-input .show-password-input {
      position: absolute !important;
      top: 50% !important;
      right: 12px !important;
      transform: translateY(-50%) !important;
      background: none !important;
      border: none !important;
      cursor: pointer !important;
      display: flex !important;
      align-items: center !important;
      justify-content: center !important;
      width: 24px !important;
      height: 24px !important;
      z-index: 3 !important;
      padding: 0 !important;
      margin: 0 !important;
      transition: outline 0.2s ease, background-color 0.2s ease;
    }

    /* 👇 Highlight SVG button on hover/focus */
    .password-input .show-password-input:hover,
    .password-input .show-password-input:focus {
      outline: 2px solid #0086ff !important;
      background-color: #e8f3ff !important;
      border-radius: 50% !important;
    }

    /* Optional: make SVG darker when focused */
    .password-input .show-password-input:hover svg,
    .password-input .show-password-input:focus svg {
      stroke: #005fcc !important;
    }

    /* Extra CSS you requested earlier */
    .password-input em + .show-password-input {
      top: 30% !important;
    }

    .password-input .show-password-input svg {
      width: 20px !important;
      height: 20px !important;
      stroke: #000000a6 !important;
      stroke-width: 2 !important;
      fill: none !important;
      pointer-events: none !important;
      display: block !important;
      transition: stroke 0.3s ease;
    }
  `;
  document.head.appendChild(style);

  const eyeSVG = `
<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24">
<path stroke-linecap="round" stroke-linejoin="round" stroke-width="2"
      d="M1.5 12s4.5-7.5 10.5-7.5S22.5 12 22.5 12s-4.5 7.5-10.5 7.5S1.5 12 1.5 12z"/>
<circle cx="12" cy="12" r="3"/>
</svg>`;
  const eyeOffSVG = `
<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24">
<path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M3 3l18 18"/>
<path stroke-linecap="round" stroke-linejoin="round" stroke-width="2"
      d="M10.73 5.08A9.77 9.77 0 0112 4.5c6 0 10.5 7.5 10.5 7.5a20.94 20.94 0 01-3.49 3.89"/>
<path stroke-linecap="round" stroke-linejoin="round" stroke-width="2"
      d="M6.12 6.11A20.94 20.94 0 001.5 12s4.5 7.5 10.5 7.5c.86 0 1.69-.09 2.49-.26"/>
</svg>`;

  function removeExtraButtons() {
    document.querySelectorAll('.show-password-input[aria-describedby]').forEach(btn => btn.remove());
  }

  function ensureToggleForInput(input) {
    if (!input || input.dataset.hasPwToggle === '1') return;
    const nextBtn = input.parentNode.querySelector('.show-password-input[aria-describedby]');
    if (nextBtn) nextBtn.remove();
    let wrapper = input.closest('.password-input');
    if (!wrapper) {
      wrapper = document.createElement('span');
      wrapper.className = 'password-input';
      input.parentNode.insertBefore(wrapper, input);
      wrapper.appendChild(input);
    }
    if (wrapper.querySelector('.show-password-input')) {
      input.dataset.hasPwToggle = '1';
      return;
    }

    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'show-password-input';
    btn.setAttribute('aria-label', 'Toggle password visibility');
    btn.innerHTML = eyeSVG;
    wrapper.appendChild(btn);
    input.dataset.hasPwToggle = '1';

    // Click toggle
    btn.addEventListener('click', function(e) {
      e.preventDefault();
      const wasPwd = input.type === 'password';
      input.type = wasPwd ? 'text' : 'password';
      btn.innerHTML = wasPwd ? eyeOffSVG : eyeSVG;
      input.classList.add('highlighted');
      setTimeout(() => input.classList.remove('highlighted'), 800);
      btn.focus();
    });

    // Enter key toggle
    btn.addEventListener('keydown', function(e) {
      if (e.key === 'Enter') {
        e.preventDefault();
        const wasPwd = input.type === 'password';
        input.type = wasPwd ? 'text' : 'password';
        btn.innerHTML = wasPwd ? eyeOffSVG : eyeSVG;
        input.classList.add('highlighted');
        setTimeout(() => input.classList.remove('highlighted'), 800);
        btn.focus();
      }
    });

    // Prevent submit on Enter inside password field
    input.addEventListener('keydown', function(e) {
      if (e.key === 'Enter') {
        e.preventDefault();
        return false;
      }
    });
  }

  function scanAndEnsure() {
    removeExtraButtons();
    document.querySelectorAll('input[type="password"]').forEach(ensureToggleForInput);
  }

  const observer = new MutationObserver(() => scanAndEnsure());
  observer.observe(document.body, { childList: true, subtree: true });
  document.addEventListener('DOMContentLoaded', scanAndEnsure);
  window.addEventListener('load', scanAndEnsure);
  setTimeout(scanAndEnsure, 1000);
  setTimeout(scanAndEnsure, 2000);
})();

(function() {
