                clearTimeout(timer);
                // 300ms is usually the "sweet spot" for intent
                timer = setTimeout(() => {
                    // Close other open menus first
                    navItems.forEach(i => {
                        if(i !== item) i.classList.remove('intent-hover');
                    });
                    item.classList.add('intent-hover');
                }, 300); 
            });

            item.addEventListener('mouseleave', () => {
                clearTimeout(timer);
                // Keep open long enough to move mouse into the dropdown
                timer = setTimeout(() => {
                    item.classList.remove('intent-hover');
                }, 400);
            });
        });
    })();

