jQuery(function($){

        function scrollToWPFormsError(){

            var $target = $(
                '.wpforms-error-container:visible,' +
                '.wpforms-field input.wpforms-error:first,' +
                '.wpforms-field select.wpforms-error:first,' +
                '.wpforms-field textarea.wpforms-error:first'
            ).first();

            if(!$target.length){
                return;
            }

            var scrollTop = $target.offset().top - 120;

            $('html, body').stop(true).animate({
                scrollTop: scrollTop
            }, 600);

            if($target.is('input, select, textarea')){
                $target.focus();
            }
        }

        // After page load (server validation)
        $(window).on('load', function () {
            setTimeout(scrollToWPFormsError, 300);
        });

        // After AJAX validation
        $(document).on('wpformsAjaxSubmitFailed wpformsAjaxSubmitError', function () {
            setTimeout(scrollToWPFormsError, 300);
        });

    });

(function($){

